mapper.select:
		/** [sql-restore.xml] RestoreMapper.getChangeDataYn - 반납요청관리 창고/구역 변경 여부 조회 true:변경 **/
        SELECT (CASE WHEN NVL(COUNT(*), 0) > 0 THEN 0 ELSE 1 END) AS CHANGE_YN
        FROM TB_ST_11
        WHERE ST11_COMPANY = #{st11Company}
          AND ST11_FACTORY = #{st11Factory}
          AND ST11_NO = #{st11No}
          AND ST11_STOK = #{st11Stok}
          AND ST11_DISTRICT = #{st11Dist}

mapper.insert:
	/** [sql-restore.xml] RestoreMapper.updateReturnForReg **/
    UPDATE TB_ST_11
       SET ST11_STOK 		= #{st11Stok}
         , ST11_DISTRICT 	= #{st11Dist}
         , ST11_UPD_EMPNO 	= #{st11UpdEmpno}
         , ST11_UPDTE 		= SYSDATE
     WHERE ST11_COMPANY 	= #{st11Company}
       AND ST11_FACTORY 	= #{st11Factory}
       AND ST11_NO 			= #{st11No}

/** [sql-restore.xml] RestoreMapper.saveOfProductionOutput **/
/* saveOfProductionOutput - 출고수량등록및변경 */ SELECT NVL(MAX(ST03_SEQ)+1,1) AS st03_seq FROM TB_ST_03 WHERE 1 = 1
AND ST03_DAT BETWEEN TO_DATE(#{st02Dat}, 'YYYY-MM-DD') AND TO_DATE(#{st02Dat}, 'YYYY-MM-DD') + 0.99999
AND ST03_DAT BETWEEN TRUNC(SYSDATE) AND TRUNC(SYSDATE) + 0.99999
AND ST03_COMPANY = #{st11Company} AND ST03_FACTORY = #{st11Factory}
/* saveOfProductionOutput - 반납출고 등록 */ MERGE INTO TB_ST_03 T1 USING DUAL ON ( ST03_COMPANY = #{st11Company} AND ST03_FACTORY = #{st11Factory} AND ST03_RENO = #{st11No} ) WHEN MATCHED THEN UPDATE SET ST03_QTY = #{st02Qty} , ST03_INDTE = SYSDATE WHEN NOT MATCHED THEN INSERT ( ST03_COMPANY, ST03_FACTORY, ST03_NO, ST03_DAT, ST03_SEQ, ST03_CODE, ST03_LOT, ST03_LOT_SEQ, ST03_GBN, ST03_UNT, ST03_QTY, ST03_STOK, ST03_INDTE, ST03_EMPNO, ST03_RENO ) VALUES ( #{st11Company}, #{st11Factory},
CONCAT(REPLACE(#{st02Dat},'-',''),LPAD(#{st03Seq},5,'0')),
CONCAT(TO_CHAR(SYSDATE, 'YYYYMMDD'),LPAD(#{st03Seq},5,'0')),
TO_DATE(REPLACE(#{st02Dat},'-',''), 'YYYYMMDD'),
TO_CHAR(SYSDATE, 'YYYYMMDD'),
#{st03Seq}, #{st11Code}, #{st11Lot}, #{st11LotSeq}, 'RE', /* 반납 - st03_gbn */ #{cm08Opunt}, #{st02Qty}, #{st11Stok}, SYSDATE, #{st11Empno}, #{st11No} )

/** [sql-restore.xml] RestoreMapper.insertOfPdStock **/
/* insertOfPdStock - 반납 재고 등록 */ SELECT NVL(MAX(ST01_LOT_SEQ)+1,1) AS st01LotSeq FROM TB_ST_01 WHERE 1 = 1 AND ST01_COMPANY = #{st11Company} AND ST01_FACTORY = #{st11Factory}
INSERT INTO TB_ST_01 ( ST01_COMPANY, ST01_FACTORY, ST01_GBN, ST01_LOT, ST01_LOT_SEQ, ST01_CODE, ST01_STOK, ST01_DISTRICT, ST01_FIELD, ST01_UNT, ST01_QTY ) VALUES ( #{st11Company}, #{st11Factory}, #{cm08Gbn}, (#{cm08Gbn}||#{cm08Dgbn}||TO_CHAR(SYSDATE, 'YYYYMMDD')), /* LOT번호 신규 생성 - 입고라서 */ #{st01LotSeq}, /* LOT번호 시퀀스 신규 생성 - 입고라서 */ #{st11Code}, #{st11Stok}, #{st11Dist}, null, #{cm08Opunt}, #{st02Qty} )
